        H("OccupationMoments"),
        Blocks(
            Describe.Lean(DescribeId.Create("hc-occupation-occupationmoments-configurations-erase-eq-filter"),
                DeclarationHandle.Create("D5/S3/StatisticalMechanics/HardCore/OccupationMoments.configurations_erase_eq_filter"),
                H("configurations erase eq filter"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Actual configurations omitting a vertex are exactly those on the erased vertex domain. The marked vertex need not belong to the domain."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("hc-occupation-occupationmoments-occupied-weight-add-erased"),
