                H("occupied weight add erased"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Partition the full configuration weight by actual root occupancy, before any division. This semiring identity also holds at zeros of a partition."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("hc-occupation-occupationmoments-weighted-cardinality-eq-marked-sum"),
                DeclarationHandle.Create("D5/S3/StatisticalMechanics/HardCore/OccupationMoments.weighted_cardinality_eq_marked_sum"),
                H("weighted cardinality eq marked sum"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Count each weighted independent configuration once per occupied vertex. This is an exact finite double-counting identity; no independence of vertex indicators is assumed."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("hc-occupation-occupationmoments-weighted-cardinality-eq-partition-differences"),
                DeclarationHandle.Create("D5/S3/StatisticalMechanics/HardCore/OccupationMoments.weighted_cardinality_eq_partition_differences"),
