                H("moment"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Unnormalized occupation moment on the original configuration family. Order zero is the existing partition; no replacement graph model is introduced."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("hc-occupation-occupationmoments-moment-zero-order"),
                DeclarationHandle.Create("D5/S3/StatisticalMechanics/HardCore/OccupationMoments.moment_zero_order"),
                H("moment zero order"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("The zeroth moment is exactly the existing constant-activity partition."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("hc-occupation-occupationmoments-moment-one-eq-deletions"),
                DeclarationHandle.Create("D5/S3/StatisticalMechanics/HardCore/OccupationMoments.moment_one_eq_deletions"),
