            Describe.Lean(DescribeId.Create("hc-occupation-occupationmoments-moment-succ-at-zero"),
                DeclarationHandle.Create("D5/S3/StatisticalMechanics/HardCore/OccupationMoments.moment_succ_at_zero"),
                H("moment succ at zero"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Every positive-order occupation moment vanishes at zero activity."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("hc-occupation-occupationmoments-moment-has-deriv-at"),
